insert into public.topics (slug, title, category, icon, summary, level, beginner_friendly, popular, introduction, what_you_will_learn, applications, prerequisites, core_concepts, roadmap, related, sort_order) values
  ('programming-fundamentals', 'Programming Fundamentals', 'software-development', 'terminal', 'Variables, logic, functions and how to think like a programmer.', 'beginner', true, true, 'Programming is the skill of giving a computer precise instructions. The fundamentals (variables, conditions, loops, functions and data structures) are the same in almost every language, so learning them once pays off for your whole career.', array['How programs store and change data with variables and types', 'How to make decisions and repeat work with conditions and loops', 'How to organise code into reusable functions', 'How to read error messages and debug methodically']::text[], array['Automating repetitive tasks at work', 'The foundation for web, mobile, data and AI careers', 'Solving problems logically in any technical field']::text[], array['Basic computer skills', 'Curiosity and patience: no maths beyond school level']::text[], '[{"title":"Variables and types","description":"Named boxes that hold numbers, text, true/false values and collections."},{"title":"Control flow","description":"if/else decisions and for/while loops that control which code runs."},{"title":"Functions","description":"Reusable blocks of code that take inputs and return outputs."},{"title":"Data structures","description":"Lists, dictionaries and sets for organising related data."},{"title":"Debugging","description":"Reading errors, printing values and isolating problems step by step."}]'::jsonb, '[{"title":"Pick one language","description":"Python is a friendly first choice; JavaScript if you want to build websites."},{"title":"Learn the core syntax","description":"Variables, conditions, loops and functions with small daily exercises."},{"title":"Solve small problems","description":"Practise on beginner exercises until the basics feel natural."},{"title":"Build a tiny project","description":"A calculator, quiz or to-do list ties the concepts together."}]'::jsonb, array['data-structures-and-algorithms', 'web-development', 'software-engineering']::text[], 0),
  ('web-development', 'Web Development', 'software-development', 'globe', 'How websites and web apps are built, from HTML to deployment.', 'beginner', true, true, 'Web development is building websites and web applications that run in a browser. It combines the frontend (what users see), the backend (servers and data) and the infrastructure that delivers it all over the internet.', array['How the browser, HTTP and servers work together', 'Structuring and styling pages with HTML and CSS', 'Adding interactivity with JavaScript', 'Publishing a site so anyone can visit it']::text[], array['Business and portfolio websites', 'Web apps such as dashboards and online stores', 'Internal tools for companies']::text[], array['Programming fundamentals are helpful but you can learn them alongside']::text[], '[{"title":"HTTP and the browser","description":"Requests, responses, URLs and what happens when you open a page."},{"title":"HTML","description":"The structure and meaning of content on a page."},{"title":"CSS","description":"Layout, colour, typography and responsive design."},{"title":"JavaScript","description":"The programming language of the browser."},{"title":"Hosting and deployment","description":"Putting a site on a server or platform with a domain."}]'::jsonb, '[{"title":"HTML and CSS","description":"Build static pages and learn responsive layouts with Flexbox and Grid."},{"title":"JavaScript basics","description":"DOM manipulation, events and fetching data from APIs."},{"title":"A framework","description":"Learn a component framework such as React."},{"title":"Backend and deployment","description":"Add a simple API and deploy your project online."}]'::jsonb, array['frontend-development', 'backend-development', 'full-stack-development']::text[], 1),
  ('frontend-development', 'Frontend Development', 'software-development', 'layers', 'Building fast, accessible user interfaces for the web.', 'beginner', true, true, 'Frontend development focuses on everything users see and interact with in the browser. Modern frontend work combines HTML, CSS and JavaScript with component frameworks, accessibility and performance.', array['Semantic HTML and accessible interfaces', 'Modern CSS layouts and responsive design', 'Component-based UIs with React', 'State management, data fetching and performance basics']::text[], array['Interactive web applications', 'Design systems and component libraries', 'Marketing sites and e-commerce storefronts']::text[], array['HTML and CSS basics', 'JavaScript fundamentals']::text[], '[{"title":"Components","description":"Small reusable UI pieces composed into pages."},{"title":"State","description":"Data that changes over time and drives what the UI shows."},{"title":"Accessibility","description":"Making interfaces usable with keyboards and screen readers."},{"title":"Performance","description":"Loading less, rendering efficiently and measuring Core Web Vitals."},{"title":"TypeScript","description":"Adding types to JavaScript to catch mistakes early."}]'::jsonb, '[{"title":"Master the platform","description":"Solid HTML, CSS and modern JavaScript (ES modules, async/await)."},{"title":"Learn React","description":"Components, props, state and effects."},{"title":"Add TypeScript and a framework","description":"Use Next.js for routing, rendering and deployment."},{"title":"Polish","description":"Accessibility, testing and performance on real projects."}]'::jsonb, array['web-development', 'full-stack-development', 'mobile-development']::text[], 2),
  ('backend-development', 'Backend Development', 'software-development', 'server', 'APIs, databases, authentication and server-side logic.', 'intermediate', false, false, 'Backend development is the server side of software: the APIs, business logic, databases and integrations that power applications. Backend engineers care about correctness, security and scale.', array['Designing REST APIs', 'Working with relational databases and SQL', 'Authentication, authorisation and security basics', 'Caching, background jobs and deployment']::text[], array['APIs for web and mobile apps', 'Payment, booking and messaging systems', 'Data processing services']::text[], array['Programming fundamentals', 'Basic command line usage']::text[], '[{"title":"APIs","description":"Contracts that let clients request data and actions over HTTP."},{"title":"Databases","description":"Storing data safely with schemas, queries and indexes."},{"title":"Auth","description":"Proving who a user is and controlling what they may do."},{"title":"Caching","description":"Storing results to answer repeated requests faster."},{"title":"Observability","description":"Logs, metrics and traces that show how a service behaves."}]'::jsonb, '[{"title":"Choose a stack","description":"Node.js, Python or Go with a web framework."},{"title":"Build a CRUD API","description":"Create, read, update and delete records in a database."},{"title":"Add auth and validation","description":"Protect routes and validate every input."},{"title":"Deploy and monitor","description":"Containerise, deploy and add logging."}]'::jsonb, array['database-management', 'system-design', 'full-stack-development']::text[], 3),
  ('full-stack-development', 'Full-Stack Development', 'software-development', 'boxes', 'Building complete applications, from interface to database.', 'intermediate', false, true, 'A full-stack developer builds both the frontend and the backend of an application. Frameworks like Next.js make this easier by combining UI, server code and data access in one project.', array['Connecting a frontend to an API and database', 'Server-side rendering and data fetching', 'Authentication across client and server', 'Shipping and maintaining a real product']::text[], array['Startups and side projects', 'SaaS products', 'Freelance and agency work']::text[], array['Frontend basics', 'Backend basics or willingness to learn both']::text[], '[{"title":"End-to-end data flow","description":"How a click becomes a request, a database query and an updated UI."},{"title":"Rendering strategies","description":"Static, server-rendered and client-rendered pages."},{"title":"Auth and sessions","description":"Cookies, tokens and protecting pages."},{"title":"Deployment","description":"Environments, environment variables and CI/CD."}]'::jsonb, '[{"title":"Frontend foundations","description":"HTML, CSS, JavaScript and React."},{"title":"Backend foundations","description":"APIs, SQL and authentication."},{"title":"One full-stack framework","description":"Next.js with a hosted database such as Supabase."},{"title":"Ship a product","description":"Build, deploy and iterate on a real app with users."}]'::jsonb, array['frontend-development', 'backend-development', 'web-development']::text[], 4),
  ('mobile-development', 'Mobile Development', 'software-development', 'smartphone', 'Native and cross-platform apps for iOS and Android.', 'intermediate', true, false, 'Mobile development is building apps for phones and tablets. You can build natively for each platform (Swift, Kotlin) or use cross-platform frameworks such as Flutter and React Native to share code.', array['Native versus cross-platform trade-offs', 'Building screens, navigation and forms', 'Storing data on the device and syncing with an API', 'Publishing to the App Store and Google Play']::text[], array['Consumer apps', 'Companion apps for products and services', 'Field and enterprise tools']::text[], array['Programming fundamentals']::text[], '[{"title":"Platforms","description":"iOS and Android have different guidelines, languages and stores."},{"title":"Cross-platform","description":"Flutter (Dart) and React Native (JavaScript) share one codebase."},{"title":"Navigation","description":"Stacks, tabs and deep links between screens."},{"title":"Offline data","description":"Local storage and syncing when the network returns."}]'::jsonb, '[{"title":"Choose an approach","description":"Flutter or React Native for cross-platform, Swift/Kotlin for native."},{"title":"Build basic screens","description":"Layouts, lists, forms and navigation."},{"title":"Connect to data","description":"Call an API and cache data locally."},{"title":"Publish","description":"Test on real devices and release a small app."}]'::jsonb, array['frontend-development', 'software-engineering', 'backend-development']::text[], 5),
  ('software-engineering', 'Software Engineering', 'software-development', 'code', 'Designing, testing and maintaining software as a team.', 'intermediate', false, true, 'Software engineering is the discipline of building software that keeps working as it grows. It covers version control, design, testing, code review and the processes teams use to deliver reliably.', array['Version control and collaboration with Git', 'Writing clean, testable code', 'Automated testing and continuous integration', 'Design principles and code review']::text[], array['Working effectively in professional teams', 'Maintaining large codebases', 'Shipping features without breaking existing ones']::text[], array['Comfortable programming in at least one language']::text[], '[{"title":"Version control","description":"Tracking every change with Git and collaborating via pull requests."},{"title":"Testing","description":"Unit, integration and end-to-end tests that catch regressions."},{"title":"Clean code","description":"Readable names, small functions and clear responsibilities."},{"title":"Design principles","description":"Separation of concerns, abstraction and avoiding duplication."},{"title":"Delivery","description":"CI/CD pipelines, code review and incremental releases."}]'::jsonb, '[{"title":"Git daily","description":"Branches, commits, merges and pull requests."},{"title":"Test what you write","description":"Add unit tests to your projects."},{"title":"Learn design principles","description":"Refactor an old project using what you learn."},{"title":"Contribute","description":"Open source or team projects with code review."}]'::jsonb, array['system-design', 'data-structures-and-algorithms', 'devops']::text[], 6),
  ('system-design', 'System Design', 'software-development', 'workflow', 'Architecting scalable, reliable distributed systems.', 'advanced', false, true, 'System design is planning how the components of a large system fit together: services, databases, caches, queues and networks. It is about trade-offs between scalability, reliability, cost and simplicity.', array['Scaling reads and writes', 'Choosing between SQL and NoSQL storage', 'Caching, queues and load balancing', 'Reasoning about consistency and availability']::text[], array['Designing backend architecture', 'Senior engineering interviews', 'Planning infrastructure for growth']::text[], array['Backend development experience', 'Databases and networking basics']::text[], '[{"title":"Scalability","description":"Vertical vs horizontal scaling and stateless services."},{"title":"Load balancing","description":"Distributing traffic across servers."},{"title":"Caching","description":"CDNs, in-memory caches and invalidation."},{"title":"Data partitioning","description":"Replication and sharding of databases."},{"title":"Consistency","description":"The CAP theorem and eventual consistency."}]'::jsonb, '[{"title":"Learn the building blocks","description":"Load balancers, caches, queues and databases."},{"title":"Study real architectures","description":"Read engineering blogs and case studies."},{"title":"Practise designs","description":"Design a URL shortener, chat app and news feed."},{"title":"Go deeper","description":"Distributed consensus, observability and failure modes."}]'::jsonb, array['backend-development', 'cloud-computing', 'database-management']::text[], 7),
  ('data-structures-and-algorithms', 'Data Structures and Algorithms', 'software-development', 'blocks', 'Efficient ways to organise data and solve problems.', 'intermediate', false, true, 'Data structures organise data so it can be used efficiently, and algorithms are step-by-step procedures for solving problems. Together they help you write faster code and are central to technical interviews.', array['Big-O notation for reasoning about performance', 'Arrays, linked lists, stacks, queues, hash maps, trees and graphs', 'Sorting, searching, recursion and dynamic programming', 'Problem-solving patterns for interviews']::text[], array['Writing efficient software', 'Technical interviews', 'Search engines, maps and recommendation systems']::text[], array['Programming fundamentals', 'Basic school algebra']::text[], '[{"title":"Complexity","description":"Big-O describes how time and memory grow with input size."},{"title":"Linear structures","description":"Arrays, linked lists, stacks and queues."},{"title":"Hashing","description":"Hash maps for near-constant-time lookups."},{"title":"Trees and graphs","description":"Hierarchies and networks, with traversal algorithms."},{"title":"Dynamic programming","description":"Solving problems by reusing answers to sub-problems."}]'::jsonb, '[{"title":"Big-O and arrays","description":"Learn to analyse simple loops."},{"title":"Core structures","description":"Implement each structure yourself once."},{"title":"Algorithms","description":"Sorting, binary search, recursion, BFS and DFS."},{"title":"Pattern practice","description":"Solve problems grouped by pattern."}]'::jsonb, array['programming-fundamentals', 'software-engineering', 'system-design']::text[], 8),
  ('artificial-intelligence', 'Artificial Intelligence', 'artificial-intelligence', 'brain', 'Systems that reason, learn and act intelligently.', 'beginner', true, true, 'Artificial intelligence is the field of building systems that perform tasks normally requiring human intelligence: recognising images, understanding language, making decisions. Today most practical AI is built with machine learning.', array['The history and main branches of AI', 'Search, reasoning and machine learning approaches', 'Where modern AI succeeds and where it fails', 'Ethical and societal considerations']::text[], array['Assistants and chatbots', 'Medical imaging and diagnostics', 'Recommendation and fraud detection']::text[], array['Programming fundamentals (Python recommended)']::text[], '[{"title":"Search and planning","description":"Finding a sequence of actions that reaches a goal."},{"title":"Knowledge and reasoning","description":"Representing facts and drawing conclusions."},{"title":"Machine learning","description":"Learning patterns from data instead of hand-written rules."},{"title":"AI safety and ethics","description":"Bias, transparency and responsible deployment."}]'::jsonb, '[{"title":"Understand the landscape","description":"What AI, ML, deep learning and generative AI each mean."},{"title":"Learn Python and maths basics","description":"Linear algebra, probability and NumPy."},{"title":"Take an intro AI course","description":"Search, logic, probability and learning."},{"title":"Specialise","description":"Machine learning, NLP, computer vision or agents."}]'::jsonb, array['machine-learning', 'deep-learning', 'generative-ai']::text[], 9),
  ('machine-learning', 'Machine Learning', 'artificial-intelligence', 'chart', 'Teaching computers to learn patterns from data.', 'intermediate', true, true, 'Machine learning is a branch of AI where computers learn from examples instead of following hand-written rules. A model is trained on data, evaluated on data it has not seen and then used to make predictions.', array['Supervised, unsupervised and reinforcement learning', 'Training, validating and testing models', 'Classic algorithms: regression, trees, clustering', 'Avoiding overfitting and measuring performance']::text[], array['Price and demand forecasting', 'Spam and fraud detection', 'Recommendations and personalisation']::text[], array['Python', 'Basic statistics and linear algebra']::text[], '[{"title":"Supervised learning","description":"Learning from labelled examples to predict outcomes."},{"title":"Unsupervised learning","description":"Finding structure, such as clusters, in unlabelled data."},{"title":"Features","description":"The input variables a model learns from."},{"title":"Overfitting","description":"When a model memorises training data and fails on new data."},{"title":"Evaluation","description":"Accuracy, precision, recall and cross-validation."}]'::jsonb, '[{"title":"Python data stack","description":"NumPy, pandas and Matplotlib."},{"title":"Core algorithms","description":"Linear/logistic regression, trees and k-means with scikit-learn."},{"title":"Evaluation and tuning","description":"Train/test splits, metrics and hyperparameters."},{"title":"End-to-end projects","description":"From raw dataset to a deployed model."}]'::jsonb, array['deep-learning', 'data-science', 'mlops']::text[], 10),
  ('deep-learning', 'Deep Learning', 'artificial-intelligence', 'network', 'Neural networks that power modern AI.', 'advanced', false, false, 'Deep learning uses neural networks with many layers to learn directly from raw data such as images, audio and text. It powers computer vision, speech recognition and large language models.', array['How neural networks and backpropagation work', 'Convolutional networks for images', 'Sequence models and transformers', 'Training at scale with PyTorch']::text[], array['Image recognition', 'Speech and translation', 'Large language models']::text[], array['Machine learning basics', 'Linear algebra and calculus fundamentals', 'Python']::text[], '[{"title":"Neurons and layers","description":"Weighted sums passed through non-linear activations."},{"title":"Backpropagation","description":"Computing gradients to update weights."},{"title":"Optimisation","description":"Gradient descent variants such as Adam."},{"title":"CNNs","description":"Networks that exploit spatial structure in images."},{"title":"Transformers","description":"Attention-based models for sequences and language."}]'::jsonb, '[{"title":"Intuition first","description":"Understand neurons, layers and gradients visually."},{"title":"Build from scratch","description":"Implement a tiny network to understand backprop."},{"title":"Use a framework","description":"Train models in PyTorch."},{"title":"Modern architectures","description":"CNNs, transformers and fine-tuning."}]'::jsonb, array['machine-learning', 'computer-vision', 'large-language-models']::text[], 11),
  ('natural-language-processing', 'Natural Language Processing', 'artificial-intelligence', 'message', 'Teaching computers to understand and generate language.', 'advanced', false, false, 'Natural language processing (NLP) is how computers work with human language: classifying text, extracting meaning, translating and generating responses. Transformers have made NLP dramatically more capable.', array['Tokenisation and text representation', 'Word embeddings and language models', 'Transformer models such as BERT', 'Fine-tuning models for real tasks']::text[], array['Search and question answering', 'Sentiment analysis', 'Translation and summarisation']::text[], array['Machine learning basics', 'Python']::text[], '[{"title":"Tokenisation","description":"Splitting text into units a model can process."},{"title":"Embeddings","description":"Dense vectors that capture meaning."},{"title":"Attention","description":"Letting a model focus on relevant words."},{"title":"Fine-tuning","description":"Adapting a pre-trained model to a specific task."}]'::jsonb, '[{"title":"Text basics","description":"Tokenisation, bag-of-words and TF-IDF."},{"title":"Embeddings","description":"Word2Vec and contextual embeddings."},{"title":"Transformers","description":"BERT-style and GPT-style models."},{"title":"Apply","description":"Fine-tune with Hugging Face on a real dataset."}]'::jsonb, array['large-language-models', 'deep-learning', 'generative-ai']::text[], 12),
  ('computer-vision', 'Computer Vision', 'artificial-intelligence', 'eye', 'Enabling machines to interpret images and video.', 'advanced', false, false, 'Computer vision teaches computers to understand images and video: recognising objects, detecting faces, segmenting scenes and tracking movement. Most modern vision systems are built on deep learning.', array['How images are represented as numbers', 'Image classification with CNNs', 'Object detection and segmentation', 'Using pre-trained models and transfer learning']::text[], array['Medical imaging', 'Self-driving and driver assistance', 'Quality inspection in manufacturing']::text[], array['Deep learning basics', 'Python']::text[], '[{"title":"Pixels and channels","description":"Images as grids of numbers."},{"title":"Convolutions","description":"Filters that detect edges, textures and shapes."},{"title":"Detection","description":"Locating objects with bounding boxes."},{"title":"Segmentation","description":"Labelling every pixel in an image."}]'::jsonb, '[{"title":"Image basics","description":"Load and transform images with OpenCV."},{"title":"Classification","description":"Train a CNN and use transfer learning."},{"title":"Detection","description":"Run and fine-tune a detection model."},{"title":"Project","description":"Build an end-to-end vision app."}]'::jsonb, array['deep-learning', 'machine-learning', 'robotics']::text[], 13),
  ('generative-ai', 'Generative AI', 'artificial-intelligence', 'sparkles', 'Models that create text, images, audio and code.', 'intermediate', true, true, 'Generative AI refers to models that create new content (text, images, audio, video and code) learned from large datasets. It includes large language models, diffusion models for images and multimodal systems.', array['How generative models differ from predictive models', 'Prompting techniques and their limits', 'Retrieval-augmented generation (RAG)', 'Responsible use: hallucination, bias and copyright']::text[], array['Writing and coding assistants', 'Image and design generation', 'Customer support and knowledge search']::text[], array['Programming basics are helpful for building with APIs']::text[], '[{"title":"Foundation models","description":"Large models pre-trained on broad data and adapted to many tasks."},{"title":"Prompting","description":"Designing inputs that guide a model''s output."},{"title":"RAG","description":"Grounding answers in your own documents."},{"title":"Diffusion models","description":"Generating images by gradually removing noise."},{"title":"Evaluation","description":"Measuring quality, accuracy and safety of outputs."}]'::jsonb, '[{"title":"Use the tools","description":"Experiment with assistants and image generators critically."},{"title":"Learn the concepts","description":"Tokens, embeddings, context windows and sampling."},{"title":"Build with an API","description":"Create a small app using a model API."},{"title":"Add retrieval","description":"Build a RAG app over your own documents."}]'::jsonb, array['large-language-models', 'ai-agents', 'natural-language-processing']::text[], 14),
  ('large-language-models', 'Large Language Models', 'artificial-intelligence', 'bot', 'How LLMs work and how to build with them.', 'advanced', false, true, 'Large language models (LLMs) are transformer networks trained on vast amounts of text to predict the next token. With further training they follow instructions, write code and reason through problems.', array['The transformer architecture and attention', 'Pre-training, fine-tuning and alignment', 'Embeddings, context windows and tokenisation', 'Building reliable applications on top of LLMs']::text[], array['Chat assistants', 'Code generation', 'Document analysis and summarisation']::text[], array['Deep learning basics', 'Python']::text[], '[{"title":"Tokens","description":"The pieces of text a model reads and predicts."},{"title":"Transformer","description":"Stacked attention and feed-forward layers."},{"title":"Instruction tuning","description":"Training models to follow instructions helpfully."},{"title":"Parameter-efficient fine-tuning","description":"Techniques such as LoRA that adapt large models cheaply."},{"title":"Evaluation","description":"Benchmarks and task-specific tests for quality."}]'::jsonb, '[{"title":"Intuition","description":"Watch an accessible introduction to LLMs."},{"title":"Build a tiny GPT","description":"Implement a small transformer from scratch."},{"title":"Read the key papers","description":"Attention, GPT-3, instruction tuning."},{"title":"Apply","description":"Fine-tune or build a RAG system with open tools."}]'::jsonb, array['generative-ai', 'natural-language-processing', 'llmops']::text[], 15),
  ('ai-agents', 'AI Agents', 'artificial-intelligence', 'workflow', 'LLM systems that plan, use tools and take actions.', 'advanced', false, false, 'AI agents are systems in which a language model decides which steps to take, which tools to call and when a task is complete. Building good agents is about clear tools, guardrails and evaluation.', array['The reasoning-and-acting loop behind agents', 'Designing tools and function calling', 'Memory, planning and multi-step workflows', 'Evaluating and constraining agent behaviour']::text[], array['Research and coding assistants', 'Workflow automation', 'Customer support automation']::text[], array['Experience using LLM APIs', 'Python or TypeScript']::text[], '[{"title":"Tool use","description":"Letting a model call functions and APIs."},{"title":"ReAct loop","description":"Interleaving reasoning steps with actions."},{"title":"Memory","description":"Keeping relevant context across steps and sessions."},{"title":"Guardrails","description":"Limits, approvals and checks for safe behaviour."}]'::jsonb, '[{"title":"Function calling","description":"Give a model one tool and handle its calls."},{"title":"Agent loop","description":"Build a simple loop that plans and acts."},{"title":"Frameworks","description":"Try an agent framework and compare with your own loop."},{"title":"Evaluate","description":"Create test tasks and measure success rates."}]'::jsonb, array['large-language-models', 'generative-ai', 'llmops']::text[], 16),
  ('cloud-computing', 'Cloud Computing', 'cloud-infrastructure', 'cloud', 'Renting computing power, storage and services on demand.', 'beginner', true, true, 'Cloud computing means using servers, storage, databases and other services over the internet instead of owning hardware. Providers such as AWS, Azure and Google Cloud let teams scale up and down on demand.', array['IaaS, PaaS and SaaS service models', 'Core services: compute, storage, networking, databases', 'Pricing, regions and availability', 'Security and the shared responsibility model']::text[], array['Hosting websites and apps', 'Data storage and analytics', 'Machine learning at scale']::text[], array['Basic networking and Linux knowledge helps']::text[], '[{"title":"Service models","description":"IaaS, PaaS and SaaS: how much the provider manages."},{"title":"Regions and zones","description":"Where resources run and how they stay available."},{"title":"Elasticity","description":"Scaling resources automatically with demand."},{"title":"Shared responsibility","description":"What the provider secures and what you must secure."}]'::jsonb, '[{"title":"Fundamentals","description":"Learn the concepts with a provider''s free fundamentals course."},{"title":"Hands-on","description":"Deploy a virtual machine and a static website."},{"title":"Core services","description":"Storage, databases, IAM and networking."},{"title":"Infrastructure as code","description":"Recreate your setup with Terraform."}]'::jsonb, array['aws', 'microsoft-azure', 'google-cloud']::text[], 17),
  ('aws', 'AWS', 'cloud-infrastructure', 'cloud', 'Amazon Web Services, the largest cloud platform.', 'intermediate', true, false, 'Amazon Web Services (AWS) is a cloud platform offering hundreds of services for computing, storage, databases, networking and AI. Its core services are widely used across the industry.', array['EC2, S3, RDS, Lambda and VPC fundamentals', 'Identity and Access Management (IAM)', 'Cost management and the free tier', 'Preparing for the Cloud Practitioner certification']::text[], array['Web application hosting', 'Serverless backends', 'Data lakes and analytics']::text[], array['Cloud computing basics']::text[], '[{"title":"IAM","description":"Users, roles and least-privilege policies."},{"title":"Compute","description":"EC2 virtual machines and Lambda functions."},{"title":"Storage","description":"S3 object storage and EBS volumes."},{"title":"Networking","description":"VPCs, subnets and security groups."}]'::jsonb, '[{"title":"Account safety","description":"Set up MFA, billing alerts and an IAM user."},{"title":"Core services","description":"S3, EC2 and IAM hands-on."},{"title":"Serverless","description":"Build an API with Lambda."},{"title":"Certify (optional)","description":"Cloud Practitioner, then Solutions Architect Associate."}]'::jsonb, array['cloud-computing', 'devops', 'kubernetes']::text[], 18),
  ('microsoft-azure', 'Microsoft Azure', 'cloud-infrastructure', 'cloud', 'Microsoft''s cloud platform, popular in enterprises.', 'intermediate', true, false, 'Microsoft Azure is a cloud platform tightly integrated with Microsoft''s ecosystem, including Windows Server, Active Directory and .NET. It is widely used by enterprises and offers strong AI services.', array['Azure resource groups, subscriptions and regions', 'Virtual machines, App Service and Functions', 'Microsoft Entra ID for identity', 'Preparing for AZ-900 fundamentals']::text[], array['Enterprise application hosting', 'Hybrid cloud setups', 'AI and data services']::text[], array['Cloud computing basics']::text[], '[{"title":"Resource groups","description":"Logical containers for related resources."},{"title":"Compute options","description":"VMs, App Service, Functions and containers."},{"title":"Identity","description":"Microsoft Entra ID (formerly Azure AD)."},{"title":"Governance","description":"Policies, tags and cost management."}]'::jsonb, '[{"title":"Fundamentals","description":"Follow Microsoft Learn''s AZ-900 path."},{"title":"Hands-on","description":"Deploy a web app with App Service."},{"title":"Identity and security","description":"Configure Entra ID and role-based access."},{"title":"Automate","description":"Use the Azure CLI or Bicep/Terraform."}]'::jsonb, array['cloud-computing', 'aws', 'google-cloud']::text[], 19),
  ('google-cloud', 'Google Cloud', 'cloud-infrastructure', 'cloud', 'Google''s cloud platform, strong in data and AI.', 'intermediate', true, false, 'Google Cloud is Google''s public cloud platform. It is known for data analytics with BigQuery, managed Kubernetes with GKE and machine learning services.', array['Projects, IAM and billing on Google Cloud', 'Compute Engine, Cloud Run and GKE', 'Cloud Storage and BigQuery', 'Vertex AI basics']::text[], array['Data warehousing and analytics', 'Containerised applications', 'Machine learning pipelines']::text[], array['Cloud computing basics']::text[], '[{"title":"Projects","description":"The organising unit for resources and billing."},{"title":"Serverless","description":"Cloud Run and Cloud Functions."},{"title":"BigQuery","description":"A serverless data warehouse queried with SQL."},{"title":"GKE","description":"Managed Kubernetes."}]'::jsonb, '[{"title":"Fundamentals","description":"Explore the docs and free tier."},{"title":"Deploy","description":"Run a container on Cloud Run."},{"title":"Data","description":"Load and query a public dataset in BigQuery."},{"title":"Scale","description":"Deploy to GKE."}]'::jsonb, array['cloud-computing', 'kubernetes', 'big-data']::text[], 20),
  ('devops', 'DevOps', 'cloud-infrastructure', 'workflow', 'Automating how software is built, tested and released.', 'intermediate', false, true, 'DevOps is a set of practices that bring development and operations together. It focuses on automation, continuous integration and delivery, infrastructure as code and monitoring.', array['Linux, shell scripting and Git', 'CI/CD pipelines', 'Containers and orchestration', 'Infrastructure as code and monitoring']::text[], array['Faster, safer releases', 'Reliable infrastructure', 'Platform engineering']::text[], array['Linux command line', 'Basic programming']::text[], '[{"title":"CI/CD","description":"Automatically testing and deploying every change."},{"title":"Containers","description":"Packaging apps with their dependencies."},{"title":"Infrastructure as code","description":"Defining servers and networks in versioned files."},{"title":"Observability","description":"Metrics, logs, traces and alerting."},{"title":"Culture","description":"Shared ownership, blameless postmortems and small batches."}]'::jsonb, '[{"title":"Linux and Git","description":"Get comfortable with the shell and version control."},{"title":"CI/CD","description":"Build a pipeline with GitHub Actions."},{"title":"Containers","description":"Docker, then Kubernetes."},{"title":"IaC and monitoring","description":"Terraform plus Prometheus/Grafana."}]'::jsonb, array['docker', 'kubernetes', 'cloud-computing']::text[], 21),
  ('mlops', 'MLOps', 'cloud-infrastructure', 'gauge', 'Deploying and maintaining machine learning in production.', 'advanced', false, false, 'MLOps applies DevOps practices to machine learning. It covers experiment tracking, reproducible training, model deployment, monitoring for drift and retraining.', array['Experiment tracking and model registries', 'Reproducible training pipelines', 'Serving models behind APIs', 'Monitoring data and model drift']::text[], array['Production ML systems', 'Recommendation and forecasting platforms', 'Regulated ML with audit trails']::text[], array['Machine learning', 'Docker and basic DevOps']::text[], '[{"title":"Experiment tracking","description":"Recording parameters, metrics and artefacts."},{"title":"Model registry","description":"Versioning and promoting models."},{"title":"Serving","description":"Batch and real-time inference."},{"title":"Monitoring","description":"Detecting drift and performance decay."}]'::jsonb, '[{"title":"Track experiments","description":"Use MLflow in a training project."},{"title":"Package and serve","description":"Wrap a model in an API and container."},{"title":"Automate","description":"Build a training and deployment pipeline."},{"title":"Monitor","description":"Add drift detection and alerts."}]'::jsonb, array['machine-learning', 'devops', 'llmops']::text[], 22),
  ('aiops', 'AIOps', 'cloud-infrastructure', 'cpu', 'Using AI to run IT operations.', 'advanced', false, false, 'AIOps (AI for IT operations) applies machine learning and analytics to operational data such as logs, metrics and alerts. The goal is to detect incidents earlier, reduce alert noise and speed up root-cause analysis.', array['Operational data: logs, metrics, traces and events', 'Anomaly detection on time series', 'Alert correlation and noise reduction', 'Automated remediation patterns']::text[], array['Incident detection in large systems', 'Capacity planning', 'Reducing on-call fatigue']::text[], array['DevOps and observability basics', 'Machine learning basics']::text[], '[{"title":"Observability data","description":"The raw signals that describe system health."},{"title":"Anomaly detection","description":"Spotting unusual patterns in metrics."},{"title":"Event correlation","description":"Grouping related alerts into one incident."},{"title":"Automation","description":"Runbooks triggered by detected conditions."}]'::jsonb, '[{"title":"Observability","description":"Collect metrics and logs from a sample app."},{"title":"Baselines","description":"Learn statistical anomaly detection."},{"title":"Correlation","description":"Group alerts and find likely causes."},{"title":"Automate","description":"Trigger safe remediation scripts."}]'::jsonb, array['devops', 'mlops', 'machine-learning']::text[], 23),
  ('llmops', 'LLMOps', 'cloud-infrastructure', 'bot', 'Operating LLM applications reliably in production.', 'advanced', false, false, 'LLMOps is the practice of running applications built on large language models in production. It covers prompt and model versioning, evaluation, cost and latency control, observability and safety.', array['Evaluating LLM outputs systematically', 'Prompt and model versioning', 'Tracing, cost and latency monitoring', 'Guardrails and safety checks']::text[], array['Production chatbots and assistants', 'RAG systems at scale', 'Agent platforms']::text[], array['Experience building LLM applications', 'DevOps basics']::text[], '[{"title":"Evaluation sets","description":"Test cases that measure quality before each change."},{"title":"Tracing","description":"Recording each model call, tool call and token count."},{"title":"Cost control","description":"Caching, model routing and prompt length."},{"title":"Guardrails","description":"Input/output filtering and policy checks."}]'::jsonb, '[{"title":"Build a baseline app","description":"A small RAG or chat application."},{"title":"Add evaluation","description":"Create a test set and automate scoring."},{"title":"Observe","description":"Add tracing, cost and latency dashboards."},{"title":"Harden","description":"Guardrails, fallbacks and staged rollouts."}]'::jsonb, array['large-language-models', 'mlops', 'ai-agents']::text[], 24),
  ('docker', 'Docker', 'cloud-infrastructure', 'container', 'Packaging applications into portable containers.', 'beginner', true, true, 'Docker packages an application and everything it needs into a container that runs the same way on any machine. Containers are the standard unit of deployment in modern infrastructure.', array['Images, containers and registries', 'Writing Dockerfiles', 'Volumes and networking', 'Running multi-container apps with Docker Compose']::text[], array['Consistent development environments', 'Deploying microservices', 'CI pipelines']::text[], array['Command line basics']::text[], '[{"title":"Image","description":"A read-only template with your app and its dependencies."},{"title":"Container","description":"A running instance of an image."},{"title":"Dockerfile","description":"Instructions for building an image."},{"title":"Compose","description":"Defining multi-container applications in YAML."}]'::jsonb, '[{"title":"Run containers","description":"Pull and run existing images."},{"title":"Build images","description":"Write a Dockerfile for your own app."},{"title":"Compose","description":"Run an app with a database using Docker Compose."},{"title":"Ship","description":"Push to a registry and deploy."}]'::jsonb, array['kubernetes', 'devops', 'cloud-computing']::text[], 25),
  ('kubernetes', 'Kubernetes', 'cloud-infrastructure', 'boxes', 'Orchestrating containers at scale.', 'advanced', false, true, 'Kubernetes is an open-source system for deploying, scaling and managing containerised applications across clusters of machines. It has become the standard platform for running containers in production.', array['Pods, deployments and services', 'Configuration with ConfigMaps and Secrets', 'Scaling, rolling updates and health checks', 'Ingress, storage and Helm']::text[], array['Running microservices', 'Platform engineering', 'Hybrid and multi-cloud deployments']::text[], array['Docker', 'Linux and networking basics']::text[], '[{"title":"Pod","description":"The smallest deployable unit, wrapping one or more containers."},{"title":"Deployment","description":"Keeps the desired number of pods running."},{"title":"Service","description":"A stable network address for a set of pods."},{"title":"Control plane","description":"The components that schedule and reconcile state."}]'::jsonb, '[{"title":"Local cluster","description":"Run minikube or kind on your machine."},{"title":"Core objects","description":"Deploy an app with a Deployment and Service."},{"title":"Operations","description":"Rolling updates, probes and autoscaling."},{"title":"Ecosystem","description":"Helm, ingress controllers and managed Kubernetes."}]'::jsonb, array['docker', 'devops', 'cloud-computing']::text[], 26),
  ('data-science', 'Data Science', 'data', 'chart', 'Turning data into insight with statistics and code.', 'intermediate', true, true, 'Data science combines statistics, programming and domain knowledge to extract insight from data. A data scientist cleans data, explores it, builds models and communicates findings.', array['Data cleaning and exploration with pandas', 'Statistics and hypothesis testing', 'Data visualisation', 'Predictive modelling and communicating results']::text[], array['Business decision-making', 'Healthcare and research', 'Product analytics']::text[], array['Python basics', 'School-level statistics']::text[], '[{"title":"Data wrangling","description":"Cleaning, joining and reshaping data."},{"title":"Exploratory analysis","description":"Summaries and charts that reveal patterns."},{"title":"Statistics","description":"Distributions, sampling and significance."},{"title":"Modelling","description":"Using machine learning to predict and explain."}]'::jsonb, '[{"title":"Python for data","description":"pandas, NumPy and Jupyter notebooks."},{"title":"Statistics","description":"Descriptive and inferential statistics."},{"title":"Visualisation","description":"Matplotlib and clear storytelling with charts."},{"title":"Projects","description":"Analyse real public datasets end to end."}]'::jsonb, array['data-analytics', 'machine-learning', 'sql']::text[], 27),
  ('data-analytics', 'Data Analytics', 'data', 'gauge', 'Answering business questions with data and dashboards.', 'beginner', true, false, 'Data analytics is about answering specific questions with data: what happened, why, and what to do next. Analysts work with SQL, spreadsheets, BI tools and clear visual communication.', array['Asking good analytical questions', 'Querying data with SQL', 'Building dashboards and reports', 'Presenting insights to non-technical audiences']::text[], array['Marketing and sales reporting', 'Operations and finance analysis', 'Product metrics']::text[], array['Spreadsheet basics']::text[], '[{"title":"Metrics","description":"Defining what to measure and why."},{"title":"SQL","description":"Filtering, grouping and joining tables."},{"title":"Visualisation","description":"Choosing the right chart for the question."},{"title":"Storytelling","description":"Turning numbers into decisions."}]'::jsonb, '[{"title":"Spreadsheets","description":"Formulas, pivot tables and charts."},{"title":"SQL","description":"Learn queries on real datasets."},{"title":"BI tools","description":"Build a dashboard in a BI tool."},{"title":"Portfolio","description":"Publish two or three analyses."}]'::jsonb, array['sql', 'data-science', 'database-management']::text[], 28),
  ('data-engineering', 'Data Engineering', 'data', 'workflow', 'Building pipelines that move and transform data.', 'intermediate', false, true, 'Data engineering is building the systems that collect, store, transform and deliver data reliably. Data engineers design pipelines, warehouses and lakes that analysts and ML teams depend on.', array['Batch and streaming pipelines', 'Data warehouses and data modelling', 'Workflow orchestration', 'Data quality and testing']::text[], array['Company data platforms', 'Real-time analytics', 'Feeding ML systems with clean data']::text[], array['SQL', 'Python', 'Command line basics']::text[], '[{"title":"ETL/ELT","description":"Extracting, transforming and loading data."},{"title":"Warehouses and lakes","description":"Structured analytics storage versus raw object storage."},{"title":"Orchestration","description":"Scheduling and monitoring pipeline tasks."},{"title":"Data modelling","description":"Fact and dimension tables for analytics."},{"title":"Streaming","description":"Processing events continuously as they arrive."}]'::jsonb, '[{"title":"SQL and Python","description":"Strong querying and scripting skills."},{"title":"Pipelines","description":"Build a batch pipeline with an orchestrator."},{"title":"Warehousing","description":"Model data and transform it with dbt."},{"title":"Scale","description":"Spark and streaming systems."}]'::jsonb, array['big-data', 'sql', 'data-science']::text[], 29),
  ('sql', 'SQL', 'data', 'database', 'The language for querying relational databases.', 'beginner', true, true, 'SQL (Structured Query Language) is the standard language for working with relational databases. It is one of the most useful skills in tech: developers, analysts and data scientists all use it daily.', array['SELECT, WHERE, ORDER BY and LIMIT', 'Aggregations with GROUP BY', 'Joining tables', 'Creating tables, indexes and constraints']::text[], array['Reporting and analytics', 'Application backends', 'Data pipelines']::text[], array['None']::text[], '[{"title":"Tables","description":"Rows and columns with defined types."},{"title":"Queries","description":"Selecting and filtering data."},{"title":"Joins","description":"Combining related tables."},{"title":"Aggregation","description":"Counting, summing and grouping."},{"title":"Indexes","description":"Speeding up lookups."}]'::jsonb, '[{"title":"Basics","description":"SELECT, filtering and sorting."},{"title":"Aggregation and joins","description":"GROUP BY and the different JOIN types."},{"title":"Design","description":"Normalisation, keys and constraints."},{"title":"Advanced","description":"Window functions and query performance."}]'::jsonb, array['database-management', 'data-analytics', 'backend-development']::text[], 30),
  ('database-management', 'Database Management', 'data', 'server', 'Designing, running and securing databases.', 'intermediate', false, false, 'Database management covers designing schemas, keeping data consistent, tuning performance, backing up and securing databases. It spans relational systems such as PostgreSQL and NoSQL systems.', array['Relational design and normalisation', 'Transactions and ACID guarantees', 'Indexing and query optimisation', 'Backups, replication and access control']::text[], array['Running production databases', 'Designing application schemas', 'Data governance']::text[], array['SQL']::text[], '[{"title":"Normalisation","description":"Structuring tables to avoid duplication."},{"title":"Transactions","description":"Grouping operations that succeed or fail together."},{"title":"Indexing","description":"Data structures that speed up queries."},{"title":"Replication","description":"Copies of data for availability and scale."},{"title":"Security","description":"Roles, permissions and row-level security."}]'::jsonb, '[{"title":"Design","description":"Model a real application''s schema."},{"title":"PostgreSQL","description":"Install, query and administer it."},{"title":"Performance","description":"Read query plans and add indexes."},{"title":"Operations","description":"Backups, restores and replication."}]'::jsonb, array['sql', 'backend-development', 'system-design']::text[], 31),
  ('big-data', 'Big Data', 'data', 'layers', 'Processing data too large for a single machine.', 'advanced', false, false, 'Big data refers to datasets too large or fast for a single machine. Distributed systems such as Apache Spark split the work across clusters to process terabytes of data.', array['Distributed storage and compute', 'Apache Spark and its DataFrame API', 'Partitioning and performance tuning', 'Lakehouse architectures']::text[], array['Log and clickstream analysis', 'Large-scale ML feature generation', 'Scientific data processing']::text[], array['SQL', 'Python', 'Data engineering basics']::text[], '[{"title":"Distribution","description":"Splitting data and work across many machines."},{"title":"MapReduce","description":"The map-then-reduce model behind distributed processing."},{"title":"Spark","description":"A fast, general engine for distributed data processing."},{"title":"Partitioning","description":"Organising data to minimise shuffling."}]'::jsonb, '[{"title":"Concepts","description":"Why distribution is needed and its trade-offs."},{"title":"Spark locally","description":"Run Spark on your laptop with PySpark."},{"title":"Real datasets","description":"Process a large public dataset."},{"title":"Cloud","description":"Run jobs on a managed cluster."}]'::jsonb, array['data-engineering', 'google-cloud', 'data-science']::text[], 32),
  ('cybersecurity', 'Cybersecurity', 'security-networking', 'shield', 'Protecting systems, networks and data from attacks.', 'beginner', true, true, 'Cybersecurity is the practice of protecting systems, networks and data from attacks, damage and unauthorised access. It ranges from secure coding to incident response and risk management.', array['The CIA triad: confidentiality, integrity, availability', 'Common threats and vulnerabilities', 'Defensive controls and secure configuration', 'Incident response basics']::text[], array['Protecting organisations and users', 'Secure software development', 'Compliance and risk management']::text[], array['Basic networking and operating system knowledge']::text[], '[{"title":"CIA triad","description":"The three goals of security."},{"title":"Threats","description":"Phishing, malware, ransomware and social engineering."},{"title":"Vulnerabilities","description":"Weaknesses such as the OWASP Top 10."},{"title":"Defence in depth","description":"Layering controls so one failure isn''t fatal."},{"title":"Incident response","description":"Detect, contain, eradicate and recover."}]'::jsonb, '[{"title":"Foundations","description":"Networking, Linux and security concepts."},{"title":"Hands-on labs","description":"Practise in legal training environments."},{"title":"Specialise","description":"Web security, blue team, cloud security or GRC."},{"title":"Certify (optional)","description":"Entry-level certifications if they suit your goals."}]'::jsonb, array['network-security', 'ethical-hacking', 'cryptography']::text[], 33),
  ('ethical-hacking', 'Ethical Hacking', 'security-networking', 'terminal', 'Finding vulnerabilities legally, before attackers do.', 'intermediate', false, false, 'Ethical hacking is authorised testing of systems to find vulnerabilities before malicious attackers do. Penetration testers follow a methodology and always work with written permission and a defined scope.', array['The legal and ethical rules of engagement', 'Reconnaissance and scanning', 'Common web and network vulnerabilities', 'Writing clear, actionable reports']::text[], array['Penetration testing', 'Bug bounty programmes', 'Red teaming']::text[], array['Networking', 'Linux command line', 'Cybersecurity basics']::text[], '[{"title":"Authorisation","description":"Only test systems you own or have written permission to test."},{"title":"Reconnaissance","description":"Gathering information about the target scope."},{"title":"Exploitation","description":"Demonstrating impact of a vulnerability safely."},{"title":"Reporting","description":"Explaining risk and remediation clearly."}]'::jsonb, '[{"title":"Linux and networking","description":"Command line fluency and TCP/IP."},{"title":"Web security","description":"Work through free web security labs."},{"title":"Practice ranges","description":"Use legal CTFs and intentionally vulnerable apps."},{"title":"Methodology","description":"Learn structured testing and reporting."}]'::jsonb, array['cybersecurity', 'network-security', 'networking']::text[], 34),
  ('networking', 'Networking', 'security-networking', 'network', 'How computers communicate, from cables to the internet.', 'beginner', true, false, 'Computer networking is how devices exchange data, from local Wi-Fi to the global internet. Understanding networks helps with development, cloud, DevOps and security work.', array['The OSI and TCP/IP models', 'IP addressing and subnetting', 'DNS, HTTP and other core protocols', 'Routing, switching and troubleshooting']::text[], array['Network administration', 'Cloud networking', 'Diagnosing application problems']::text[], array['None']::text[], '[{"title":"Layers","description":"OSI and TCP/IP models describe how data moves."},{"title":"IP addressing","description":"IPv4, IPv6 and subnets."},{"title":"TCP and UDP","description":"Reliable versus fast transport."},{"title":"DNS","description":"Translating names to IP addresses."}]'::jsonb, '[{"title":"Models","description":"Learn the layers and what each does."},{"title":"Addressing","description":"Practise subnetting."},{"title":"Protocols","description":"Inspect real traffic with Wireshark."},{"title":"Practice","description":"Build a home lab or cloud VPC."}]'::jsonb, array['network-security', 'cloud-computing', 'cybersecurity']::text[], 35),
  ('network-security', 'Network Security', 'security-networking', 'lock', 'Defending networks with firewalls, monitoring and design.', 'intermediate', false, false, 'Network security protects the infrastructure that connects systems. It covers secure network design, firewalls, VPNs, intrusion detection and monitoring traffic for threats.', array['Secure network architecture and segmentation', 'Firewalls, VPNs and zero trust', 'Intrusion detection and traffic analysis', 'Common network attacks and defences']::text[], array['Corporate network defence', 'Cloud network security', 'Security operations centres']::text[], array['Networking fundamentals']::text[], '[{"title":"Segmentation","description":"Dividing networks to limit an attacker''s movement."},{"title":"Firewalls","description":"Rules that allow or block traffic."},{"title":"Zero trust","description":"Never trust by location; always verify."},{"title":"Monitoring","description":"Detecting suspicious traffic patterns."}]'::jsonb, '[{"title":"Networking","description":"Solid TCP/IP and routing knowledge."},{"title":"Controls","description":"Configure firewalls and VPNs in a lab."},{"title":"Detection","description":"Analyse traffic and alerts."},{"title":"Architecture","description":"Design a segmented, zero-trust network."}]'::jsonb, array['networking', 'cybersecurity', 'cryptography']::text[], 36),
  ('cryptography', 'Cryptography', 'security-networking', 'key', 'The mathematics of secure communication.', 'advanced', false, false, 'Cryptography is the science of protecting information using mathematics. It secures web traffic, passwords, payments and messaging. Most developers need to use it correctly, not invent it.', array['Symmetric and asymmetric encryption', 'Hashing and digital signatures', 'How TLS secures the web', 'Common mistakes and how to avoid them']::text[], array['HTTPS and secure messaging', 'Password storage', 'Blockchains and digital identity']::text[], array['Programming basics', 'Some comfort with mathematics']::text[], '[{"title":"Symmetric encryption","description":"One shared key encrypts and decrypts (e.g. AES)."},{"title":"Public-key cryptography","description":"Key pairs for encryption and signatures."},{"title":"Hash functions","description":"One-way fingerprints of data."},{"title":"Key exchange","description":"Agreeing a secret over an insecure channel."}]'::jsonb, '[{"title":"Concepts","description":"Build intuition for keys, hashes and signatures."},{"title":"Use libraries","description":"Encrypt, hash and sign with well-reviewed libraries."},{"title":"Protocols","description":"Understand TLS and certificates."},{"title":"Theory","description":"Study the mathematics behind the primitives."}]'::jsonb, array['cybersecurity', 'blockchain', 'network-security']::text[], 37),
  ('blockchain', 'Blockchain', 'emerging-technologies', 'blocks', 'Distributed ledgers and how they reach consensus.', 'intermediate', true, false, 'A blockchain is a shared ledger maintained by many computers that agree on its contents without a central authority. It underpins cryptocurrencies and smart-contract platforms.', array['Blocks, hashing and chains', 'Consensus mechanisms', 'Smart contracts', 'Realistic use cases and limitations']::text[], array['Cryptocurrencies and payments', 'Decentralised applications', 'Supply-chain tracking experiments']::text[], array['Programming basics', 'Cryptography concepts help']::text[], '[{"title":"Ledger","description":"An append-only record of transactions."},{"title":"Hashing","description":"Linking blocks so history can''t be altered silently."},{"title":"Consensus","description":"Proof of work, proof of stake and agreement among nodes."},{"title":"Smart contracts","description":"Programs that run on a blockchain."}]'::jsonb, '[{"title":"Intuition","description":"Understand how a blockchain works visually."},{"title":"Original papers","description":"Read the Bitcoin and Ethereum whitepapers."},{"title":"Smart contracts","description":"Write a simple contract on a test network."},{"title":"Evaluate","description":"Study trade-offs, security and real adoption."}]'::jsonb, array['web3', 'cryptography', 'system-design']::text[], 38),
  ('web3', 'Web3', 'emerging-technologies', 'globe', 'Decentralised applications built on blockchains.', 'intermediate', false, false, 'Web3 describes applications that use blockchains for ownership, identity and payments instead of relying on a single company. It is an experimental and debated area with real security risks.', array['Wallets, accounts and transactions', 'Building dApps that interact with smart contracts', 'Token standards', 'Security risks and scams to avoid']::text[], array['Decentralised finance experiments', 'Digital ownership', 'Decentralised identity']::text[], array['Blockchain basics', 'JavaScript']::text[], '[{"title":"Wallets","description":"Key pairs that control blockchain accounts."},{"title":"dApps","description":"Frontends that talk to smart contracts."},{"title":"Tokens","description":"Standardised digital assets on a blockchain."},{"title":"Security","description":"Audits, common exploits and user safety."}]'::jsonb, '[{"title":"Foundations","description":"Learn blockchain concepts first."},{"title":"Developer docs","description":"Follow Ethereum''s developer documentation."},{"title":"Build","description":"Create a dApp on a test network, never with real funds."},{"title":"Security","description":"Study common smart-contract vulnerabilities."}]'::jsonb, array['blockchain', 'cryptography', 'web-development']::text[], 39),
  ('internet-of-things', 'Internet of Things', 'emerging-technologies', 'wifi', 'Connected devices, sensors and embedded systems.', 'intermediate', true, false, 'The Internet of Things (IoT) connects physical devices such as sensors, appliances and machines to the internet so they can collect data and be controlled remotely.', array['Microcontrollers and sensors', 'Communication protocols such as MQTT', 'Sending device data to the cloud', 'IoT security fundamentals']::text[], array['Smart homes', 'Industrial monitoring', 'Agriculture and environmental sensing']::text[], array['Programming basics']::text[], '[{"title":"Microcontrollers","description":"Small computers such as Arduino boards."},{"title":"Sensors and actuators","description":"Measuring the world and acting on it."},{"title":"Protocols","description":"Lightweight messaging such as MQTT."},{"title":"Edge computing","description":"Processing data close to where it is produced."}]'::jsonb, '[{"title":"Electronics basics","description":"Start with an Arduino starter project."},{"title":"Connectivity","description":"Send sensor readings over Wi-Fi."},{"title":"Cloud","description":"Store and visualise device data."},{"title":"Secure it","description":"Authentication, updates and encryption."}]'::jsonb, array['robotics', 'cloud-computing', 'networking']::text[], 40),
  ('quantum-computing', 'Quantum Computing', 'emerging-technologies', 'atom', 'Computing with qubits and quantum mechanics.', 'advanced', false, false, 'Quantum computing uses qubits, which can exist in superpositions and become entangled, to solve certain problems differently from classical computers. It is an active research field with early hardware.', array['Qubits, superposition and entanglement', 'Quantum gates and circuits', 'Famous algorithms such as Grover''s and Shor''s', 'Programming quantum circuits with Qiskit']::text[], array['Cryptography research', 'Simulating molecules and materials', 'Optimisation research']::text[], array['Linear algebra', 'Python']::text[], '[{"title":"Qubit","description":"The quantum unit of information."},{"title":"Superposition","description":"A qubit can be in a combination of states."},{"title":"Entanglement","description":"Correlations between qubits with no classical equivalent."},{"title":"Quantum circuits","description":"Sequences of gates applied to qubits."}]'::jsonb, '[{"title":"Maths","description":"Vectors, matrices and complex numbers."},{"title":"Concepts","description":"Build intuition with visual explanations."},{"title":"Circuits","description":"Write and simulate circuits with Qiskit."},{"title":"Algorithms","description":"Study Grover''s and Shor''s algorithms."}]'::jsonb, array['cryptography', 'artificial-intelligence', 'data-structures-and-algorithms']::text[], 41),
  ('robotics', 'Robotics', 'emerging-technologies', 'cpu', 'Machines that sense, decide and act in the physical world.', 'advanced', false, false, 'Robotics combines mechanical engineering, electronics and software to build machines that perceive and act. Modern robotics relies on frameworks such as ROS 2 and increasingly on machine learning.', array['Sensors, actuators and control loops', 'Robot Operating System (ROS 2)', 'Localisation and path planning', 'Using computer vision in robots']::text[], array['Manufacturing and logistics', 'Autonomous vehicles and drones', 'Medical robotics']::text[], array['Programming (Python or C++)', 'Basic physics and maths']::text[], '[{"title":"Kinematics","description":"How robot joints and links move."},{"title":"Control","description":"Feedback loops such as PID."},{"title":"Perception","description":"Understanding the environment from sensors."},{"title":"Planning","description":"Finding safe paths and actions."}]'::jsonb, '[{"title":"Hardware basics","description":"Simple robots with microcontrollers."},{"title":"ROS 2","description":"Nodes, topics and simulation."},{"title":"Navigation","description":"Localisation and path planning in simulation."},{"title":"Perception","description":"Add vision for object detection."}]'::jsonb, array['internet-of-things', 'computer-vision', 'ai-agents']::text[], 42),
  ('ar-and-vr', 'AR and VR', 'emerging-technologies', 'glasses', 'Augmented and virtual reality experiences.', 'intermediate', true, false, 'Augmented reality (AR) overlays digital content on the real world; virtual reality (VR) places users in fully digital environments. Both use 3D graphics, spatial tracking and new interaction design.', array['3D graphics fundamentals', 'Spatial tracking and interaction', 'Building WebXR experiences', 'Comfort and accessibility in immersive design']::text[], array['Training and simulation', 'Gaming and entertainment', 'Retail and design visualisation']::text[], array['Programming basics', 'JavaScript for WebXR']::text[], '[{"title":"3D scenes","description":"Meshes, materials, lights and cameras."},{"title":"Tracking","description":"Following head, hand and device movement."},{"title":"Interaction","description":"Selecting and manipulating objects in 3D."},{"title":"Comfort","description":"Avoiding motion sickness and fatigue."}]'::jsonb, '[{"title":"3D basics","description":"Learn a 3D library or game engine."},{"title":"WebXR","description":"Build a simple immersive scene in the browser."},{"title":"Interaction","description":"Add controllers and hand input."},{"title":"Ship","description":"Test on real devices and refine."}]'::jsonb, array['frontend-development', 'computer-vision', 'internet-of-things']::text[], 43)
