  ('yt-cs50-full-course', 'Harvard CS50 – Full Computer Science University Course', 'The complete CS50 introduction to computer science, from Scratch and C to Python, SQL and web development.', 'video', 'freeCodeCamp.org', 'https://www.youtube.com/watch?v=8mAITcNt710', 'beginner', 'free', null, 'English', null, '2026-11-24', true, 0),
