insert into public.learning_paths (slug, title, description, icon, difficulty, duration, outcome, skills, featured, sort_order) values
  ('beginner-to-software-engineer', 'Complete Beginner to Software Engineer', 'Go from never having coded to building, testing and shipping software like a professional engineer.', 'rocket', 'beginner', '9–12 months part-time', 'You can build and ship well-structured applications, use Git in a team and pass entry-level interviews.', array['Programming', 'Data structures', 'Git', 'Testing', 'Web basics', 'Problem solving']::text[], true, 0),
  ('full-stack-web-developer', 'Full-Stack Web Developer', 'Build complete web applications: interfaces, APIs, databases and deployment.', 'boxes', 'intermediate', '6–9 months part-time', 'You can design, build and deploy a production-ready full-stack web application.', array['HTML/CSS', 'JavaScript', 'React', 'Node.js', 'SQL', 'Next.js', 'Deployment']::text[], true, 1),
  ('frontend-developer', 'Frontend Developer', 'Craft fast, accessible and beautiful user interfaces for the web.', 'layers', 'beginner', '4–6 months part-time', 'You can build accessible, responsive, component-based interfaces with React and TypeScript.', array['HTML', 'CSS', 'JavaScript', 'React', 'TypeScript', 'Accessibility']::text[], false, 2),
  ('backend-developer', 'Backend Developer', 'Design reliable APIs, data models and services that power applications.', 'server', 'intermediate', '5–7 months part-time', 'You can build secure, well-tested APIs backed by relational databases and deploy them in containers.', array['Node.js or Python', 'REST APIs', 'SQL', 'Auth', 'Docker', 'Testing']::text[], false, 3),
  ('python-developer', 'Python Developer', 'Master Python for automation, scripting, data work and web backends.', 'terminal', 'beginner', '3–5 months part-time', 'You can write idiomatic, tested Python for automation, data analysis and simple web services.', array['Python syntax', 'Standard library', 'Automation', 'Testing', 'Packages']::text[], true, 4),
  ('ai-engineer', 'AI Engineer', 'Build products on top of large language models: RAG, agents, evaluation and deployment.', 'sparkles', 'advanced', '5–8 months part-time', 'You can design, evaluate and deploy reliable LLM-powered applications and agents.', array['Python', 'LLM APIs', 'Embeddings', 'RAG', 'Agents', 'Evaluation', 'LLMOps']::text[], true, 5),
  ('machine-learning-engineer', 'Machine Learning Engineer', 'Train, evaluate and deploy machine learning models that work in the real world.', 'brain', 'advanced', '8–12 months part-time', 'You can build ML models end to end and deploy and monitor them in production.', array['Python', 'Maths for ML', 'scikit-learn', 'PyTorch', 'MLOps', 'Model deployment']::text[], true, 6),
  ('data-scientist', 'Data Scientist', 'Use statistics, programming and machine learning to turn data into decisions.', 'chart', 'intermediate', '6–9 months part-time', 'You can analyse data, build predictive models and communicate findings clearly.', array['Python', 'Statistics', 'SQL', 'Visualisation', 'Machine learning', 'Communication']::text[], false, 7),
  ('data-engineer', 'Data Engineer', 'Build the pipelines, warehouses and platforms that every data team depends on.', 'workflow', 'intermediate', '6–9 months part-time', 'You can build reliable batch pipelines, model data for analytics and work with distributed tools.', array['SQL', 'Python', 'Data modelling', 'Orchestration', 'dbt', 'Spark', 'Cloud']::text[], true, 8),
  ('devops-engineer', 'DevOps Engineer', 'Automate delivery and run reliable infrastructure with containers, CI/CD and code.', 'container', 'intermediate', '6–9 months part-time', 'You can automate builds and deployments and run containerised workloads with monitoring.', array['Linux', 'Git', 'Docker', 'CI/CD', 'Kubernetes', 'Terraform', 'Monitoring']::text[], true, 9),
  ('cloud-engineer', 'Cloud Engineer', 'Design, build and secure infrastructure on AWS, Azure or Google Cloud.', 'cloud', 'intermediate', '5–8 months part-time', 'You can design secure, cost-aware cloud architectures and automate them with code.', array['Cloud fundamentals', 'Networking', 'IAM', 'Compute and storage', 'Terraform', 'Cost management']::text[], false, 10),
  ('cybersecurity-specialist', 'Cybersecurity Specialist', 'Learn to defend systems, test them ethically and respond to incidents.', 'shield', 'intermediate', '8–12 months part-time', 'You understand core security concepts, can test web apps ethically and harden systems.', array['Networking', 'Linux', 'Web security', 'Cryptography', 'Security operations']::text[], false, 11),
  ('mobile-app-developer', 'Mobile App Developer', 'Build and publish cross-platform mobile apps for iOS and Android.', 'smartphone', 'beginner', '4–6 months part-time', 'You can build, test and publish cross-platform mobile apps that use real data.', array['Dart or JavaScript', 'Flutter or React Native', 'State management', 'APIs', 'Publishing']::text[], false, 12)
insert into public.learning_path_stages (path_slug, stage_id, position, title, description, skills, resource_ids, exercise, project_slug) values
  ('beginner-to-software-engineer', 'foundations', 0, 'Programming foundations', 'Learn to think like a programmer with Python.', array['Variables', 'Control flow', 'Functions']::text[], array['course-cs50x', 'yt-learn-python', 'book-automate-boring']::text[], 'Write a number-guessing game and a simple to-do list in the terminal.', null),
  ('beginner-to-software-engineer', 'tools', 1, 'Developer tools', 'Get comfortable with the shell, an editor and Git.', array['Command line', 'Git', 'VS Code']::text[], array['course-missing-semester', 'book-pro-git', 'tool-vscode']::text[], 'Put all your exercises in a GitHub repository with meaningful commits.', null),
  ('beginner-to-software-engineer', 'dsa', 2, 'Data structures and algorithms', 'Learn to write efficient code and solve problems.', array['Big-O', 'Arrays and hash maps', 'Recursion']::text[], array['pl-mit-6006', 'course-neetcode', 'course-exercism']::text[], 'Solve 30 problems across arrays, strings and hash maps.', null),
  ('beginner-to-software-engineer', 'web', 3, 'Web fundamentals', 'Build for the platform almost every engineer touches.', array['HTML', 'CSS', 'JavaScript']::text[], array['doc-mdn', 'course-freecodecamp']::text[], 'Build and deploy a personal portfolio.', 'personal-portfolio'),
  ('beginner-to-software-engineer', 'engineering', 4, 'Software engineering practices', 'Write code that others can read, test and maintain.', array['Testing', 'Clean code', 'Code review']::text[], array['gh-clean-code-js', 'gh-coding-interview-university']::text[], 'Add tests to a previous project and refactor it.', null),
  ('beginner-to-software-engineer', 'capstone', 5, 'Capstone project', 'Build and ship a complete application.', array['Full-stack basics', 'Deployment']::text[], array['doc-nextjs', 'doc-supabase']::text[], 'Ship a full-stack app with authentication and a database.', 'realtime-collaborative-notes'),
  ('full-stack-web-developer', 'frontend-basics', 0, 'Frontend foundations', 'HTML, CSS and modern JavaScript.', array['Semantic HTML', 'Responsive CSS', 'ES modules']::text[], array['doc-mdn', 'book-eloquent-js', 'course-odin']::text[], 'Rebuild a landing page from a screenshot.', null),
