insert into public.projects (slug, title, category, difficulty, duration, description, technologies, skills, requirements, steps, outcome, topics, resource_ids, github_url, featured, sort_order) values
  ('personal-portfolio', 'Personal Portfolio Website', 'web', 'beginner', '1–2 weekends', 'Design and publish a fast, accessible portfolio that presents your skills and projects.', array['HTML', 'CSS', 'JavaScript', 'Git']::text[], array['Semantic HTML', 'Responsive layout', 'Basic accessibility', 'Deploying a static site']::text[], array['A code editor', 'A free GitHub account', 'Basic HTML and CSS']::text[], '[{"title":"Plan the content","description":"Write a short bio, list three projects and decide on sections."},{"title":"Build the structure","description":"Create semantic HTML: header, main, sections and footer."},{"title":"Style it","description":"Add a simple type scale and a responsive layout with Flexbox or Grid."},{"title":"Make it accessible","description":"Check colour contrast, alt text and keyboard navigation."},{"title":"Deploy","description":"Push to GitHub and publish with a static host."}]'::jsonb, 'A live portfolio site at a public URL that you can share with employers.', array['web-development', 'frontend-development']::text[], array['doc-mdn', 'course-freecodecamp', 'tool-vscode']::text[], null, true, 0),
  ('weather-dashboard', 'Weather Dashboard', 'web', 'intermediate', '1–2 weeks', 'Build a React app that searches cities and displays current weather and a forecast from a public API.', array['React', 'TypeScript', 'REST API', 'CSS']::text[], array['Fetching data from APIs', 'Loading and error states', 'Component design', 'Environment variables']::text[], array['JavaScript fundamentals', 'Basic React', 'A free API key from a weather data provider']::text[], '[{"title":"Choose an API","description":"Pick a free weather API from a public API list and read its docs."},{"title":"Scaffold the app","description":"Create a React + TypeScript project and plan the components."},{"title":"Fetch data","description":"Call the API, type the response and handle loading and errors."},{"title":"Design the UI","description":"Show current conditions, a five-day forecast and recent searches."},{"title":"Deploy","description":"Keep the API key out of Git and deploy the app."}]'::jsonb, 'A deployed, responsive dashboard that handles errors gracefully.', array['frontend-development', 'web-development']::text[], array['doc-react', 'doc-typescript', 'gh-public-apis']::text[], null, true, 1),
  ('realtime-collaborative-notes', 'Real-time Collaborative Notes', 'web', 'advanced', '3–5 weeks', 'A full-stack notes app with authentication, a Postgres database and live updates between users.', array['Next.js', 'TypeScript', 'Supabase', 'PostgreSQL']::text[], array['Authentication', 'Row Level Security', 'Real-time subscriptions', 'Full-stack deployment']::text[], array['React and Next.js experience', 'SQL basics', 'A free Supabase project']::text[], '[{"title":"Model the data","description":"Design tables for users, notes and sharing permissions."},{"title":"Secure it","description":"Write Row Level Security policies so users only see their notes."},{"title":"Build the UI","description":"Create, edit and list notes with optimistic updates."},{"title":"Go real-time","description":"Subscribe to changes so collaborators see edits instantly."},{"title":"Ship","description":"Deploy to Vercel with environment variables configured."}]'::jsonb, 'A secure, multi-user web application with live collaboration.', array['full-stack-development', 'backend-development', 'database-management']::text[], array['doc-nextjs', 'doc-supabase', 'doc-postgresql']::text[], null, false, 2),
  ('habit-tracker-app', 'Habit Tracker App', 'mobile', 'beginner', '1–2 weeks', 'A cross-platform mobile app to create habits, check them off daily and see streaks.', array['Flutter', 'Dart', 'Local storage']::text[], array['Mobile layouts', 'State management', 'Persisting data on device']::text[], array['Programming basics', 'Flutter installed with an emulator or device']::text[], '[{"title":"Design screens","description":"Sketch the habit list, add-habit form and stats screen."},{"title":"Build the list","description":"Display habits and toggle today''s completion."},{"title":"Persist data","description":"Save habits locally so they survive restarts."},{"title":"Add streaks","description":"Calculate and display current and longest streaks."},{"title":"Polish","description":"Add empty states, dark mode and test on a real device."}]'::jsonb, 'A working mobile app you can install and use every day.', array['mobile-development']::text[], array['doc-flutter', 'yt-flutter-fcc', 'gh-flutter-samples']::text[], null, false, 3),
  ('offline-expense-tracker', 'Offline-first Expense Tracker', 'mobile', 'intermediate', '2–4 weeks', 'Track expenses offline and sync with a backend when the device reconnects.', array['React Native', 'TypeScript', 'SQLite', 'REST API']::text[], array['Offline storage', 'Data synchronisation', 'Forms and validation', 'Charts']::text[], array['React basics', 'A simple backend API or hosted database']::text[], '[{"title":"Data model","description":"Define expenses, categories and sync metadata."},{"title":"Local first","description":"Store all changes on the device first."},{"title":"Sync","description":"Push and pull changes when online and resolve conflicts."},{"title":"Insights","description":"Show monthly totals and category breakdowns."},{"title":"Test","description":"Simulate offline mode and verify no data is lost."}]'::jsonb, 'A reliable app that works without a connection and syncs safely.', array['mobile-development', 'backend-development']::text[], array['doc-react-native', 'doc-typescript']::text[], null, false, 4),
  ('document-qa-rag', 'Document Q&A with RAG', 'ai', 'intermediate', '1–3 weeks', 'Answer questions about your own documents by retrieving relevant passages and grounding an LLM''s answer in them.', array['Python', 'Embeddings', 'Vector search', 'LLM API']::text[], array['Chunking and embeddings', 'Retrieval', 'Prompt design', 'Evaluating answers']::text[], array['Python', 'An LLM API key or a local model via Ollama']::text[], '[{"title":"Prepare documents","description":"Load PDFs or Markdown files and split them into chunks."},{"title":"Embed and index","description":"Create embeddings and store them in a vector index."},{"title":"Retrieve","description":"Find the most relevant chunks for each question."},{"title":"Generate","description":"Ask the model to answer only from the retrieved context, with citations."},{"title":"Evaluate","description":"Write test questions and measure answer accuracy."}]'::jsonb, 'A question-answering tool that cites the passages it used.', array['generative-ai', 'large-language-models', 'natural-language-processing']::text[], array['paper-rag', 'course-hf-learn', 'tool-ollama', 'doc-claude']::text[], null, true, 5),
  ('tool-using-agent', 'Tool-using AI Agent', 'ai', 'advanced', '2–4 weeks', 'Build an agent that plans multi-step tasks and calls tools such as search, a calculator and a file reader.', array['Python or TypeScript', 'LLM API', 'Function calling']::text[], array['Tool design', 'Agent loops', 'Guardrails', 'Agent evaluation']::text[], array['Experience with LLM APIs', 'Comfortable with async code']::text[], '[{"title":"Define tools","description":"Write two or three small, well-described functions."},{"title":"Agent loop","description":"Let the model choose tools, run them and feed back results."},{"title":"Limits","description":"Add step limits, input validation and confirmation for risky actions."},{"title":"Memory","description":"Keep a concise record of progress across steps."},{"title":"Evaluate","description":"Create a task set and measure the success rate."}]'::jsonb, 'An agent that completes multi-step tasks within safe limits.', array['ai-agents', 'large-language-models']::text[], array['paper-react', 'course-hf-agents', 'doc-claude']::text[], null, false, 6),
  ('house-price-prediction', 'House Price Prediction', 'machine-learning', 'beginner', '1 week', 'Train a regression model to predict house prices from features like size and location.', array['Python', 'pandas', 'scikit-learn', 'Jupyter']::text[], array['Data cleaning', 'Feature engineering', 'Regression', 'Model evaluation']::text[], array['Python basics', 'A public housing dataset (e.g. from Kaggle)']::text[], '[{"title":"Explore","description":"Load the data and visualise relationships."},{"title":"Clean","description":"Handle missing values and encode categories."},{"title":"Baseline","description":"Train linear regression and measure error."},{"title":"Improve","description":"Try tree-based models and tune hyperparameters."},{"title":"Explain","description":"Write up which features matter most."}]'::jsonb, 'A notebook with a trained model, metrics and a clear write-up.', array['machine-learning', 'data-science']::text[], array['doc-scikit-learn', 'course-kaggle-learn', 'tool-jupyter']::text[], null, false, 7),
  ('image-classifier-transfer-learning', 'Image Classifier with Transfer Learning', 'machine-learning', 'intermediate', '1–2 weeks', 'Fine-tune a pre-trained CNN to classify your own images and serve it through a small web demo.', array['Python', 'PyTorch', 'Pre-trained CNN', 'Gradio or FastAPI']::text[], array['Data augmentation', 'Transfer learning', 'Model evaluation', 'Model serving']::text[], array['Python and ML basics', 'A GPU via Google Colab (free tier)']::text[], '[{"title":"Collect data","description":"Gather and label a few hundred images across classes."},{"title":"Fine-tune","description":"Replace the final layer of a pre-trained model and train."},{"title":"Evaluate","description":"Use a confusion matrix to find mistakes."},{"title":"Serve","description":"Wrap the model in a simple web demo."},{"title":"Reflect","description":"Document limitations and possible bias in your data."}]'::jsonb, 'A working image classifier with a demo others can try.', array['deep-learning', 'computer-vision']::text[], array['course-fastai', 'doc-pytorch-tutorials', 'tool-colab']::text[], null, false, 8),
  ('public-dataset-analysis', 'Exploratory Analysis of a Public Dataset', 'data-science', 'beginner', '3–5 days', 'Pick a public dataset, ask three questions and answer them with clean analysis and charts.', array['Python', 'pandas', 'Matplotlib', 'Jupyter']::text[], array['Asking questions', 'Data cleaning', 'Visualisation', 'Writing findings']::text[], array['Python basics']::text[], '[{"title":"Pick a dataset","description":"Choose something you care about from a public data source."},{"title":"Ask questions","description":"Write three specific questions before touching the data."},{"title":"Clean and explore","description":"Fix types, handle missing values and summarise."},{"title":"Visualise","description":"Create one clear chart per question."},{"title":"Publish","description":"Share the notebook with a short summary of findings."}]'::jsonb, 'A published analysis that demonstrates your data skills.', array['data-science', 'data-analytics']::text[], array['book-pdsh', 'course-kaggle-learn', 'tool-jupyter']::text[], null, false, 9),
  ('sales-analytics-dashboard', 'Sales Analytics Dashboard', 'data-science', 'intermediate', '1–2 weeks', 'Model a sales dataset in SQL and build an interactive dashboard with key business metrics.', array['SQL', 'PostgreSQL', 'Python', 'A BI or charting tool']::text[], array['Data modelling', 'SQL aggregation', 'Metric design', 'Dashboard design']::text[], array['SQL basics', 'A sample sales dataset']::text[], '[{"title":"Load data","description":"Import the dataset into PostgreSQL."},{"title":"Model","description":"Create clean fact and dimension tables."},{"title":"Define metrics","description":"Revenue, growth, top products and retention."},{"title":"Build the dashboard","description":"Present metrics with filters by date and region."},{"title":"Tell the story","description":"Write three insights a manager could act on."}]'::jsonb, 'A dashboard that answers real business questions.', array['data-analytics', 'sql', 'data-engineering']::text[], array['course-sqlbolt', 'doc-postgresql', 'yt-sql-fcc']::text[], null, false, 10),
  ('containerised-ci-cd-pipeline', 'Containerise an App with a CI/CD Pipeline', 'devops', 'intermediate', '1–2 weeks', 'Package a web app in Docker and build a pipeline that tests, builds and deploys every change automatically.', array['Docker', 'GitHub Actions', 'A cloud host']::text[], array['Writing Dockerfiles', 'CI pipelines', 'Automated testing', 'Secrets management']::text[], array['A small web app with tests', 'A GitHub account', 'Docker installed']::text[], '[{"title":"Dockerise","description":"Write a Dockerfile and run the app in a container locally."},{"title":"Compose","description":"Add a database with Docker Compose for local development."},{"title":"CI","description":"Run tests and build the image on every pull request."},{"title":"CD","description":"Deploy automatically when changes merge to main."},{"title":"Harden","description":"Use secrets, small base images and image scanning."}]'::jsonb, 'A repository where every merged change is tested and deployed automatically.', array['devops', 'docker']::text[], array['doc-docker', 'yt-docker-fcc', 'gh-devops-exercises']::text[], null, true, 11),
  ('kubernetes-deployment-monitoring', 'Kubernetes Deployment with Monitoring', 'devops', 'advanced', '2–4 weeks', 'Deploy a multi-service application to Kubernetes with autoscaling, health checks and dashboards.', array['Kubernetes', 'Helm', 'Prometheus', 'Grafana']::text[], array['Kubernetes objects', 'Helm charts', 'Observability', 'Autoscaling']::text[], array['Docker experience', 'A local cluster (kind or minikube) or managed Kubernetes']::text[], '[{"title":"Cluster","description":"Create a local or managed cluster."},{"title":"Deploy","description":"Write Deployments, Services and an Ingress."},{"title":"Package","description":"Turn the manifests into a Helm chart."},{"title":"Observe","description":"Install Prometheus and Grafana and build a dashboard."},{"title":"Scale","description":"Configure probes and a Horizontal Pod Autoscaler, then load test."}]'::jsonb, 'A production-style Kubernetes deployment with metrics and autoscaling.', array['kubernetes', 'devops', 'cloud-computing']::text[], array['doc-kubernetes', 'yt-k8s-nana', 'gh-k8s-hard-way']::text[], null, false, 12),
  ('password-strength-checker', 'Password Strength Checker', 'cybersecurity', 'beginner', '2–4 days', 'A tool that rates password strength and explains how to improve it, without sending passwords anywhere.', array['Python or JavaScript']::text[], array['Password security concepts', 'Input handling', 'Entropy estimation', 'Privacy by design']::text[], array['Programming basics']::text[], '[{"title":"Research","description":"Learn what makes passwords weak: length, reuse, common patterns."},{"title":"Rules","description":"Check length, character variety and common-password lists."},{"title":"Estimate","description":"Calculate an approximate entropy score."},{"title":"Explain","description":"Give clear, specific suggestions to the user."},{"title":"Privacy","description":"Make sure everything runs locally and nothing is logged."}]'::jsonb, 'A small, privacy-respecting security tool with clear feedback.', array['cybersecurity', 'cryptography']::text[], array['course-cs50-cyber', 'gh-owasp-cheatsheets']::text[], null, false, 13),
  ('juice-shop-security-audit', 'Web App Security Audit on OWASP Juice Shop', 'cybersecurity', 'intermediate', '1–3 weeks', 'Run the intentionally vulnerable Juice Shop locally, find vulnerabilities and write a professional report.', array['OWASP Juice Shop', 'Docker', 'Browser developer tools']::text[], array['Web vulnerability testing', 'OWASP Top 10', 'Responsible reporting']::text[], array['Web basics', 'Docker', 'Only test your own local instance']::text[], '[{"title":"Set up safely","description":"Run Juice Shop locally in Docker, never against real sites."},{"title":"Learn the risks","description":"Study the OWASP Top 10 categories."},{"title":"Test","description":"Find and document vulnerabilities methodically."},{"title":"Fix","description":"Describe how each issue should be remediated."},{"title":"Report","description":"Write a clear report with severity ratings."}]'::jsonb, 'A professional-style security report you can show employers.', array['ethical-hacking', 'cybersecurity']::text[], array['gh-juice-shop', 'doc-owasp-top10', 'art-portswigger-academy']::text[], 'https://github.com/juice-shop/juice-shop', false, 14),
  ('file-organiser-script', 'Automatic File Organiser', 'automation', 'beginner', '1–3 days', 'A script that tidies your Downloads folder by moving files into folders by type and date.', array['Python', 'Standard library']::text[], array['File system operations', 'Command-line arguments', 'Safe automation (dry runs)']::text[], array['Python basics']::text[], '[{"title":"Plan rules","description":"Decide which file types go into which folders."},{"title":"Dry run","description":"Print what would happen without moving anything."},{"title":"Move files","description":"Implement moves with duplicate-name handling."},{"title":"Configure","description":"Read rules from a config file and add CLI options."},{"title":"Schedule","description":"Run it automatically on a schedule."}]'::jsonb, 'A useful everyday script that keeps your files organised.', array['programming-fundamentals']::text[], array['book-automate-boring', 'doc-python-tutorial']::text[], null, false, 15),
  ('scheduled-report-bot', 'Scheduled Web Report Bot', 'automation', 'intermediate', '1–2 weeks', 'Collect data from public APIs or feeds on a schedule and email or post a tidy summary report.', array['Python', 'REST APIs', 'GitHub Actions (scheduled)']::text[], array['API integration', 'Scheduling', 'Error handling and retries', 'Secrets management']::text[], array['Python', 'A free API and an email or chat webhook']::text[], '[{"title":"Pick sources","description":"Choose public APIs or RSS feeds and respect their terms."},{"title":"Collect","description":"Fetch and normalise the data with retries."},{"title":"Summarise","description":"Format a clean report in Markdown or HTML."},{"title":"Deliver","description":"Send it via email or a chat webhook."},{"title":"Schedule","description":"Run it daily with a scheduled CI workflow and stored secrets."}]'::jsonb, 'A hands-off bot that delivers a useful report every day.', array['programming-fundamentals', 'devops']::text[], array['gh-public-apis', 'book-automate-boring']::text[], null, false, 16)
